private string GetCellTextForHtmlExport(string strCellText)
{
    if (chkIsShowLearningSession.Checked || string.IsNullOrEmpty(strCellText))
        return strCellText;

    return RemoveLearningSessionFromCellText(strCellText);
}

private string RemoveLearningSessionFromCellText(string strCellText)
{
    string[] arrLine = strCellText.Split(new string[] { "\r\n" }, StringSplitOptions.None);
    System.Text.StringBuilder sb = new System.Text.StringBuilder();
    for (int i = 0; i < arrLine.Length; i++)
    {
        if (IsLearningSessionLine(arrLine[i]))
            continue;

        if (sb.Length > 0)
            sb.Append("\r\n");
        sb.Append(arrLine[i]);
    }
    return sb.ToString();
}

private bool IsLearningSessionLine(string strLine)
{
    if (strLine == null)
        return false;

    string str = strLine.Trim();
    if (str.Length != 11)
        return false;
    if (str[2] != ':' || str[5] != '-' || str[8] != ':')
        return false;

    for (int i = 0; i < str.Length; i++)
    {
        if (i == 2 || i == 5 || i == 8)
            continue;
        if (!char.IsDigit(str[i]))
            return false;
    }
    return true;
}

